"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 6 (P1 v0.3, sections 3-4): curate the event and decoy pools from FSD50K metadata text only.

FSD50K labels are broader than our events (e.g. "Doorbell" includes airport and stadium chimes, "Ringtone" includes
notification beeps, "Telephone" includes dialling and busy tones). Clips are assigned from their title, tags and
description by the fixed rules below plus a short manual list (each entry with its reason), before any model has
processed the audio. Input: results/step0/fsd50k_selection.json (single-source CC0/CC BY clips).

Pools: phone (incoming-call rings and ringtones), doorbell, knock, decoy (one shared list of household sounds that
are neither bell/ring-like nor knock/door-like, not human, not alarming), and two unseen event types for the
report-only subset (phone vibrating, door-entry intercom).
usage: python -I scripts/step0_curate_pools.py <selection json> <output json>
"""
import json
import re
import sys
from collections import Counter

DECOY_CLASSES = ["Dishes_and_pots_and_pans", "Cutlery_and_silverware", "Water_tap_and_faucet",
                 "Sink_(filling_or_washing)", "Frying_(food)", "Boiling", "Crumpling_and_crinkling", "Tearing",
                 "Zipper_(clothing)", "Packing_tape_and_duct_tape", "Scissors", "Writing", "Typing",
                 "Computer_keyboard"]
# not used as decoys: bird calls (tonal, ringtone-like), coins (metallic ring), typewriter (bell), tick-tock (clock),
# microwave and printer (beeps), toilet flush (another person present), drawer/cupboard (door-like), raindrop (few)

RING_POS = re.compile(r"\bring(s|ing|er|tone)?\b|ringtone|\bbell\b|incoming call|\btrill", re.I)
RING_NEG = re.compile(r"dial|dtmf|busy|touch.?tone|hang.?up|pick.?up|picking up|engaged|voice.?mail|answering|button|"
                      r"keypad|beep|vibrat|message|\bsms\b|notification|speech|talk|voice|conversation|static|modem|"
                      r"fax|off.?hook|handling|drop|slam|click", re.I)
VIBRATION = re.compile(r"vibrat|vibre", re.I)
RINGTONE_NEG = re.compile(r"notif|\bbeep|message|\bsms\b|texting|chime|interference|inteference|8-bit|bfxr|"
                          r"video game|fantasy sfx|alert\s*\d|alarm beeps", re.I)
RINGTONE_TAG = re.compile(r"ring-?tone|\bring\b|ringer|ringing|ring-alert", re.I)
DOORBELL_NEG = re.compile(r"airport|announcement|stadium|church|airplane|aircraft|seat.?belt|broadcast|signaali|"
                          r"\bpa\b|fridge|alarm|theatre|funny|\bdog\b|bark|doorclose|\bclose\b|hammer|doorknob|gears|"
                          r"terminal|remix", re.I)
INTERCOM = re.compile(r"entry.?phone|intercom|door.?phone", re.I)
KNOCK_POS = re.compile(r"knock|klopf|bussa|batend|golpe|tocar puerta|pukan|rapping|pounding|banging on", re.I)
KNOCK_NEG = re.compile(r"impact|shoulder|snowball|marble|\bball\b|revolving|escape|violence|corridor|hammering", re.I)
DECOY_NEG = re.compile(r"door|bell|phone|ring|knock|\bdog\b|bark|footstep|voice|speech|talk|singing|music|alarm|"
                       r"beep|scream|shout|laugh", re.I)

MANUAL = {  # clip id: (pool or None to drop, reason)
    "274436": ("phone", "rotary telephone ringing, four rings (description); dropped by the word 'dial'"),
    "142903": ("phone", "old dial-plate telephone rings with a shrill bell (description)"),
    "79568": ("phone", "telephone with a mechanical bell ringer (description); dropped by 'touch-tone'"),
    "271399": (None, "landline rings, then the receiver is picked up (description)"),
    "117848": (None, "imagined 'wizard's phone' sound (description)"),
    "236799": (None, "guess-the-source school recording (description)"),
    "31299": (None, "bell tapped by hand to imitate a ring (description)"),
    "7056": (None, "small electric bell: school bell, doorbell or alarm (description)"),
    "179301": (None, "stock-market office ambience with phones ringing (title)"),
    "254186": (None, "'ringing out': caller-side ringback, not an incoming ring (title)"),
    "204186": (None, "toy phone (title)"),
    "164843": (None, "school or telephone bell (title)"),
    "21680": ("unseen_vibration", "phone ringing in vibrate mode (description)"),
    "331569": (None, "generic chime, no doorbell mentioned (title, tags)"),
    "218317": (None, "doorbell with a neighbour's dog barking (title)"),
}


def text(v):
    return " ".join([v["title"], " ".join(v["tags"]), v["description"]])


def assign(k, v):
    if k in MANUAL:
        return MANUAL[k][0]
    t, title_tags = text(v), v["title"] + " " + " ".join(v["tags"])
    c = v["class"]
    if c == "Telephone":
        if VIBRATION.search(t):
            return "unseen_vibration"
        return "phone" if RING_POS.search(t) and not RING_NEG.search(t) else None
    if c == "Ringtone":
        if RINGTONE_NEG.search(title_tags):
            return None
        tags = " ".join(v["tags"])
        if re.search(r"alarm|alert", tags, re.I) and not RINGTONE_TAG.search(tags):
            return None
        return "phone"
    if c == "Doorbell":
        if INTERCOM.search(t):
            return "unseen_intercom"
        return None if DOORBELL_NEG.search(title_tags) else "doorbell"
    if c == "Knock":
        return "knock" if KNOCK_POS.search(title_tags) and not KNOCK_NEG.search(title_tags) else None
    if c in DECOY_CLASSES:
        return None if DECOY_NEG.search(title_tags) else "decoy"
    return None


def main(sel_path, out_path):
    sel = json.load(open(sel_path, encoding="utf-8"))
    pools = {}
    for k, v in sel.items():
        p = assign(k, v)
        if p:
            pools[k] = {"pool": p, "fsd50k_class": v["class"], "uploader": v["uploader"], "license": v["license"],
                        "split_fsd50k": v["split"], "title": v["title"],
                        "manual": MANUAL[k][1] if k in MANUAL else None}
    json.dump({"rules_version": 1, "decoy_classes": DECOY_CLASSES, "clips": pools}, open(out_path, "w", encoding="utf-8"),
              indent=0, ensure_ascii=False)
    by = Counter(v["pool"] for v in pools.values())
    for p in sorted(by):
        ups = {v["uploader"] for v in pools.values() if v["pool"] == p}
        print(f"{p:18s} clips {by[p]:5d}  uploaders {len(ups):4d}")
    print("decoy classes:", dict(Counter(v["fsd50k_class"] for v in pools.values() if v["pool"] == "decoy")))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
